# identify if quadrants are torus-shifted/reflected source
for i in range(2):
 for j in range(2):
  if i==j==0: continue
  Q=B[i*12:(i+1)*12,j*12:(j+1)*12]
  matches=[]
  for k in range(4):
   T=np.rot90(A,k)
   # rotated dimensions same
   for flip in [False,True]:
    U=np.fliplr(T) if flip else T
    for dr in range(12):
     for dc in range(12):
      V=np.roll(np.roll(U,dr,0),dc,1)
      # color permutations
      for p in [(2,6,7),(2,7,6),(6,2,7),(6,7,2),(7,2,6),(7,6,2)]:
       W=np.copy(V)
       for x,y in zip((2,6,7),p): W[V==x]=y
       if np.array_equal(Q,W): matches.append((k,flip,dr,dc,p))
  print(i,j,matches[:2])
